const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const appTask = document.body.dataset.task || 'store';
const fmt = cents => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(cents);
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[char]));
const api = async (url, options = {}) => {
  const headers = { ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...(state.token ? { Authorization: `Bearer ${state.token}` } : {}), ...options.headers };
  const response = await fetch(url, { ...options, headers });
  const data = response.status === 204 ? {} : await response.json().catch(() => ({}));
  if (!response.ok) { if (response.status === 401 && state.token) signOut(false); throw new Error(data.error || 'Something went wrong.'); }
  return data;
};
const state = {
  token: localStorage.getItem('studio-token') || '', user: null, products: [], bag: JSON.parse(localStorage.getItem('studio-bag') || '[]'),
  category: 'All', search: '', projects: [], projectId: null, project: null, members: [], tasks: [], activeTask: null, authMode: 'login', activeProduct: null,
  rooms: [], room: null, roomKey: null, roomAfter: 0, roomStreamController: null, roomStreamReady: null, roomFiles: new Map(), roomInviteHandled: false, roomPresence:new Map(), presenceTimer:null, roomMembers:[], roomOwnerId:null, isRoomOwner:false,
  localStream: null, screenStream: null, peers: new Map(), callClientId:crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`, callJoined: false, callStarting: null, callConnectionIssue:'', microphoneEnabled: false, cameraEnabled: false, drawing: false, boardLastSent: 0,
  boardColor:'#df6954', boardSize:5, boardEraser:false, boardUndo:[], boardMode:'pen', boardStart:null, boardPreview:null, boardLastActivity:0, speechTimer:null, speechContext:null, callSpeaking:false, roomActivity:''
};
let toastTimer;
function toast(message) { const el = $('#toast'); el.textContent = message; el.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('show'), 2600); }
function showDialog(id) { const d = document.getElementById(id); if (d && !d.open) d.showModal(); }
function closeDialog(id) { const d = document.getElementById(id); if (d?.open) d.close(); }
$$('[data-close]').forEach(button => button.addEventListener('click', () => button.closest('dialog').close()));
$$('dialog').forEach(dialog => dialog.addEventListener('click', e => { if (e.target === dialog && !dialog.classList.contains('drawer')) dialog.close(); }));
function applyTheme(theme) {
  const active = theme === 'dark' ? 'dark' : 'light';
  document.documentElement.dataset.theme = active;
  localStorage.setItem('studio-theme', active);
  const button = $('#theme-toggle');
  button.textContent = active === 'dark' ? '◐' : '◑';
  button.setAttribute('aria-label', `Switch to ${active === 'dark' ? 'light' : 'dark'} mode`);
  button.title = `Switch to ${active === 'dark' ? 'light' : 'dark'} mode`;
  const themeColors = { store: active === 'dark' ? '#171513' : '#efede9', board: active === 'dark' ? '#111914' : '#d9e1db', channel: active === 'dark' ? '#050610' : '#f1f2f8' };
  document.querySelector('meta[name="theme-color"]').content = themeColors[document.body.dataset.currentView] || themeColors.store;
}
applyTheme(localStorage.getItem('studio-theme') || (appTask === 'channel' ? 'dark' : 'light'));
$('#theme-toggle').addEventListener('click', () => applyTheme(document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark'));

async function init() {
  if (appTask === 'store') {
    $('#product-grid').innerHTML = '<div class="loading-card"></div><div class="loading-card"></div><div class="loading-card"></div><div class="loading-card"></div>';
    try { state.products = (await api('/api/products')).products; renderProducts(); }
    catch { $('#product-grid').innerHTML = ''; toast('The shop could not connect. Is the server running?'); }
    renderBag();
  }
  updateAuthButton();
  if (state.token) {
    try { const data = await api('/api/auth/me'); state.user = data.user; updateAuthButton(); }
    catch { localStorage.removeItem('studio-token'); state.token = ''; }
  }
  switchView(appTask);
}
function updateAuthButton() { const button = $('#auth-open'); button.textContent = state.user ? state.user.name.trim().split(/\s+/).map(x => x[0]).slice(0,2).join('').toUpperCase() : '↗'; button.title = state.user ? 'Open account options' : 'Sign in'; button.setAttribute('aria-label', button.title); }
function productIllustration(id) {
  const drawings = {
    1: '<path d="M42 100V83a48 48 0 0 1 96 0v17"/><rect x="32" y="92" width="25" height="45" rx="10"/><rect x="123" y="92" width="25" height="45" rx="10"/><path d="M74 47l19 8 19-8" class="art-accent"/>',
    2: '<path d="M42 69h96l-8 81H50z"/><path d="M63 72V53a27 27 0 0 1 54 0v19"/><path d="M73 103h34" class="art-accent"/><circle cx="90" cy="119" r="5" class="art-fill"/>',
    3: '<path d="M39 90h48l-5 48H45zM52 88V77a11 11 0 0 1 22 0"/><path d="M92 100h47l-5 39H98zM104 98V86a11 11 0 0 1 22 0"/><path d="M35 147h54M89 148h55" class="art-accent"/>',
    4: '<path d="M75 35h30v24l16 17v64a14 14 0 0 1-14 14H73a14 14 0 0 1-14-14V76l16-17z"/><path d="M75 49h30M60 99h61" class="art-accent"/><path d="M81 119c7-8 14-8 21 0"/>',
    5: '<path d="M44 77h92l-13-35H57z"/><path d="M90 78v44M75 122h30M64 148h52l-8-14H72z"/><path d="M90 91v22" class="art-accent"/>',
    6: '<rect x="47" y="32" width="89" height="122" rx="4"/><path d="M65 32v122M78 63h42M78 77h42M78 91h30" class="art-accent"/><circle cx="107" cy="122" r="12"/>',
    7: '<path d="M38 56l37-19 27 17 42-10v100l-41 11-29-17-36 13z"/><path d="M75 37v101M102 54v101M39 86l37-15 26 16 42-12M39 117l37-15 26 16 42-11" class="art-accent"/>',
    8: '<rect x="48" y="37" width="84" height="112" rx="8"/><circle cx="90" cy="90" r="28"/><circle cx="90" cy="90" r="13" class="art-fill"/><path d="M72 50h36M76 132h28" class="art-accent"/><circle cx="117" cy="59" r="3" class="art-fill"/>'
  };
  return `<svg class="product-illustration" viewBox="0 0 180 180" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${drawings[id] || drawings[8]}</svg>`;
}
function renderProducts() {
  const filtered = state.products.filter(p => (state.category === 'All' || p.category === state.category) && `${p.name} ${p.description} ${p.category}`.toLowerCase().includes(state.search.toLowerCase()));
  $('#product-count').textContent = `${filtered.length} ${filtered.length === 1 ? 'object' : 'objects'}`;
  $('#product-grid').innerHTML = filtered.map(p => `<article class="product-card"><button class="product-art" data-art="${p.id}" style="--product-color:${esc(p.color)}" data-product="${p.id}" aria-label="See details for ${esc(p.name)}"><span class="product-label">${p.featured ? 'Shop pick' : esc(p.category)}</span>${productIllustration(p.id)}</button><div class="product-info"><div><button class="product-name product-title-button" data-product="${p.id}">${esc(p.name)}</button><div class="product-category">${esc(p.category)}</div></div><div class="product-price">${fmt(p.price)}</div></div><button class="quick-add" data-add="${p.id}" aria-label="Add ${esc(p.name)} to bag">Add</button></article>`).join('');
  $('#empty-products').classList.toggle('hidden', filtered.length > 0);
}
function persistBag() { localStorage.setItem('studio-bag', JSON.stringify(state.bag)); renderBag(); }
function addToBag(id) { const line = state.bag.find(item => item.productId === id); if (line) line.quantity = Math.min(25, line.quantity + 1); else state.bag.push({ productId: id, quantity: 1 }); persistBag(); toast('A lovely choice. Added to your bag.'); }
function adjustBag(id, change) { const line = state.bag.find(item => item.productId === id); if (!line) return; line.quantity += change; if (line.quantity <= 0) state.bag = state.bag.filter(item => item.productId !== id); persistBag(); }
function renderBag() {
  $('#bag-count').textContent = state.bag.reduce((n, item) => n + item.quantity, 0);
  const lines = state.bag.map(line => ({ ...line, product: state.products.find(p => p.id === line.productId) })).filter(line => line.product);
  $('#bag-items').innerHTML = lines.length ? lines.map(({product:p,quantity}) => `<div class="bag-line"><div class="bag-product-art" data-art="${p.id}" style="--product-color:${esc(p.color)}">${productIllustration(p.id)}</div><div><h3 class="bag-product-name">${esc(p.name)}</h3><div class="bag-product-price">${fmt(p.price)} each</div><div class="qty-tools"><button data-qty="${p.id}" data-change="-1" aria-label="Remove one ${esc(p.name)}">−</button><span>${quantity}</span><button data-qty="${p.id}" data-change="1" aria-label="Add one ${esc(p.name)}">＋</button><button class="remove-item" data-remove="${p.id}">Remove</button></div></div><div class="bag-line-total">${fmt(p.price*quantity)}</div></div>`).join('') : '<div class="bag-empty">Your bag is taking a little breather.</div>';
  $('#bag-total').textContent = fmt(lines.reduce((sum,line) => sum + line.product.price*line.quantity,0));
  $('#checkout').disabled = !lines.length; $('#checkout').style.opacity = lines.length ? '1' : '.5';
}
function openProduct(id) {
  const p = state.products.find(product => product.id === id); if (!p) return; state.activeProduct = p;
  $('#detail-product-art').innerHTML = productIllustration(p.id); $('#detail-product-art').dataset.art=p.id; $('#detail-product-art').style.setProperty('--product-color',p.color); $('#detail-product-category').textContent=p.category;
  $('#detail-product-name').textContent=p.name; $('#detail-product-description').textContent=p.description; $('#detail-product-price').textContent=fmt(p.price);
  showDialog('product-dialog');
}
$('#product-grid').addEventListener('click', e => {
  const add = e.target.closest('[data-add]'); if (add) return addToBag(Number(add.dataset.add));
  const product = e.target.closest('[data-product]'); if (product) openProduct(Number(product.dataset.product));
});
$('#detail-product-add').addEventListener('click', () => { if (state.activeProduct) addToBag(state.activeProduct.id); closeDialog('product-dialog'); });
$('#bag-items').addEventListener('click', e => {
  const qty = e.target.closest('[data-qty]'); if (qty) return adjustBag(Number(qty.dataset.qty),Number(qty.dataset.change));
  const remove = e.target.closest('[data-remove]'); if (remove) { state.bag = state.bag.filter(line => line.productId !== Number(remove.dataset.remove)); persistBag(); }
});
$('#bag-open').addEventListener('click', () => showDialog('bag-dialog'));
$('#filters').addEventListener('click', e => { const button=e.target.closest('[data-category]'); if(!button)return; state.category=button.dataset.category; $$('.filter').forEach(el=>el.classList.toggle('active',el===button)); renderProducts(); });
$('#product-search').addEventListener('input', e => {state.search=e.target.value.trim();renderProducts();});

function setAuthMode(mode) {
  state.authMode=mode; const registering=mode==='register'; $('#auth-title').innerHTML=registering?'A fresh <em>start.</em>':'Welcome <em>back.</em>';
  const accountCopy=appTask==='store'?'your bag and orders':appTask==='board'?'your shared projects':'your private rooms';
  $('#auth-copy').textContent=registering?('Create an account to keep '+accountCopy+' together.'):('Sign in to continue to '+accountCopy+'.');
  $('#name-field').classList.toggle('hidden',!registering); $('#name-field input').required=registering;
  $('#auth-form [name="password"]').autocomplete=registering?'new-password':'current-password'; $('#auth-submit').innerHTML=registering?'Create account <span>↗</span>':'Sign in <span>↗</span>';
  $('#auth-toggle').textContent=registering?'Already have an account? Sign in':'New here? Create an account'; $('#auth-error').textContent='';
}
$('#auth-toggle').addEventListener('click',()=>setAuthMode(state.authMode==='login'?'register':'login'));
$('#auth-open').addEventListener('click',()=>{ if(state.user){$('#account-name').textContent=state.user.name;$('#account-email').textContent=state.user.email;showDialog('account-dialog');return;} setAuthMode('login'); showDialog('auth-dialog'); });
$('#signout-open').addEventListener('click',()=>{closeDialog('account-dialog');showDialog('signout-dialog');});
$('#signout-confirm').addEventListener('click',async()=>{closeDialog('signout-dialog');await signOut(true);});
$('#auth-form').addEventListener('submit',async e=>{
  e.preventDefault();const form=new FormData(e.currentTarget);const payload=Object.fromEntries(form.entries());const endpoint=state.authMode==='register'?'/api/auth/register':'/api/auth/login';$('#auth-submit').disabled=true;$('#auth-error').textContent='';
  try{const data=await api(endpoint,{method:'POST',body:JSON.stringify(payload)});state.token=data.token;state.user=data.user;localStorage.setItem('studio-token',state.token);closeDialog('auth-dialog');updateAuthButton();if(appTask==='board')await loadProjects();if(appTask==='channel'){await loadRooms();await handleRoomInvite();}toast(`Welcome in, ${state.user.name.split(' ')[0]}.`);}
  catch(err){$('#auth-error').textContent=err.message;}finally{$('#auth-submit').disabled=false;}
});
async function signOut(notify=true){if(state.token){try{await api('/api/auth/logout',{method:'POST'});}catch{}}if(state.room)sendRoomPresence('leave');clearInterval(state.presenceTimer);state.presenceTimer=null;state.roomPresence.clear();state.roomStreamController?.abort();await leaveCall(false);state.room=null;state.roomKey=null;state.roomInviteHandled=false;state.user=null;state.token='';state.project=null;state.members=[];state.rooms=[];for(const key of Object.keys(sessionStorage))if(key.startsWith('openroom-key-'))sessionStorage.removeItem(key);for(const key of Object.keys(localStorage))if(key.startsWith('openroom-key-'))localStorage.removeItem(key);localStorage.removeItem('studio-token');state.projects=[];state.tasks=[];$('#room-active').classList.add('hidden');$('#room-empty').classList.remove('hidden');renderRoomList();updateAuthButton();renderBoard();if(notify)toast('You’re signed out. See you soon.');}
$('#checkout').addEventListener('click',()=>{if(!state.user){closeDialog('bag-dialog');setAuthMode('login');showDialog('auth-dialog');toast('Sign in to place your demo order.');}else{closeDialog('bag-dialog');showDialog('checkout-dialog');}});
$('#checkout-form').addEventListener('submit',async e=>{e.preventDefault();$('#checkout-error').textContent='';try{const data=await api('/api/orders',{method:'POST',body:JSON.stringify({items:state.bag})});state.bag=[];persistBag();closeDialog('checkout-dialog');toast(`Demo order #${data.orderId} placed. Thank you!`);}catch(err){$('#checkout-error').textContent=err.message;}});

$$('.nav-link').forEach(button=>button.addEventListener('click',()=>switchView(button.dataset.view)));
function switchView(view){if(view!==appTask)return;const changed=document.body.dataset.currentView!==view;$$('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$$('.view').forEach(el=>el.classList.toggle('active',el.id===`${view}-view`));document.body.dataset.currentView=view;applyTheme(document.documentElement.dataset.theme);if(changed){document.body.classList.remove('project-swishing');void document.body.offsetWidth;document.body.classList.add('project-swishing');setTimeout(()=>document.body.classList.remove('project-swishing'),520);}if((view==='board'||view==='channel')&&!state.user){setAuthMode('login');showDialog('auth-dialog');toast('Sign in to open your shared spaces.');}else if(view==='board')loadProjects().catch(err=>toast(err.message));else if(view==='channel')loadRooms().then(handleRoomInvite).catch(err=>toast(err.message));window.scrollTo({top:0,behavior:'smooth'});}

async function loadProjects(){
  if(!state.user)return;const data=await api('/api/projects');state.projects=data.projects;
  if(!state.projects.length){state.projectId=null;state.project=null;state.members=[];state.tasks=[];renderBoard();return;}
  if(!state.projects.some(project=>project.id===state.projectId))state.projectId=state.projects[0].id;
  renderProjectSelector();await loadProject();
}
function renderProjectSelector(){const select=$('#project-select');select.innerHTML=state.projects.map(p=>`<option value="${p.id}" ${p.id===state.projectId?'selected':''}>${esc(p.name)}</option>`).join('');}
function setBoardTone(projectId){const tone=['clay','mint','blue'][Math.abs(Number(projectId)-1)%3];$('#board-view').dataset.boardTone=tone;document.body.dataset.boardTone=tone;}
async function loadProject(){if(!state.projectId)return;const [data,memberData]=await Promise.all([api(`/api/projects/${state.projectId}`),api(`/api/projects/${state.projectId}/members`)]);state.project=data.project;state.members=memberData.members;state.tasks=data.tasks;$('#project-name').textContent=data.project.name;$('#project-description').textContent=data.project.description||'A quiet space to get good things done.';setBoardTone(data.project.id);$('#share-project').classList.toggle('hidden',data.project.user_id!==state.user.id);$('#task-form [name="assignee"]').innerHTML='<option value="">No one yet</option>'+state.members.map(m=>`<option value="${esc(m.name)}">${esc(m.name)}</option>`).join('');renderBoard();}
function renderBoard(){
  if(!state.user){$('#task-columns').innerHTML='<div class="board-signin"><h2>A place for the work ahead.</h2><p>Sign in to make your own project space.</p><button class="button button-dark" id="board-signin">Sign in <span>↗</span></button></div>';$('#board-signin')?.addEventListener('click',()=>{setAuthMode('login');showDialog('auth-dialog');});$('#board-summary').innerHTML='';$('#project-select').innerHTML='';$('#share-project').classList.add('hidden');$('#project-name').textContent='Your workspace';$('#project-description').textContent='Your next good thing starts here.';return;}
  const done=state.tasks.filter(t=>t.status==='done').length, progress=state.tasks.filter(t=>t.status==='inprogress').length, todo=state.tasks.filter(t=>t.status==='todo').length;
  $('#board-summary').innerHTML=`<span class="summary-pill"><i class="summary-dot"></i><strong>${todo}</strong> to do</span><span class="summary-pill"><i class="summary-dot active"></i><strong>${progress}</strong> in progress</span><span class="summary-pill"><i class="summary-dot done"></i><strong>${done}</strong> complete</span>`;
  const cols=[['todo','To do'],['inprogress','In progress'],['done','Done']];
  $('#task-columns').innerHTML=cols.map(([status,label])=>{const tasks=state.tasks.filter(t=>t.status===status);return `<section class="task-column" data-drop-status="${status}"><div class="column-heading"><div class="column-title"><i class="summary-dot ${status==='inprogress'?'active':status==='done'?'done':''}"></i>${label}<span class="column-count">${tasks.length}</span></div>${status==='todo'?'<button class="add-task-small" id="add-task" aria-label="Add a task">＋</button>':''}</div>${tasks.length?tasks.map(taskCard).join(''):'<div class="column-empty">Nothing on the docket yet.</div>'}</section>`;}).join('');
  $$('.task-card', $('#task-columns')).forEach(card=>card.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',card.dataset.taskId);e.dataTransfer.effectAllowed='move';}));
  $$('.task-column', $('#task-columns')).forEach(column=>{column.addEventListener('dragover',e=>{e.preventDefault();column.classList.add('drag-over');});column.addEventListener('dragleave',()=>column.classList.remove('drag-over'));column.addEventListener('drop',async e=>{e.preventDefault();column.classList.remove('drag-over');const id=Number(e.dataTransfer.getData('text/plain'));await updateTask(id,{status:column.dataset.dropStatus});});});
}
function taskCard(t){const due=t.due_date?new Date(`${t.due_date}T00:00:00`).toLocaleDateString('en-IN',{day:'numeric',month:'short'}):'';return `<article class="task-card" draggable="true" data-task-id="${t.id}" tabindex="0" role="button" aria-label="Open task ${esc(t.title)}"><span class="task-priority ${esc(t.priority)}">${esc(t.priority)} priority</span><h3>${esc(t.title)}</h3>${t.description?`<p>${esc(t.description)}</p>`:''}<div class="task-meta">${t.assignee?`<span class="task-assignee" title="${esc(t.assignee)}">${esc(t.assignee.split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase())}</span>`:''}<span class="task-comments">◷ ${t.comment_count||0}</span>${due?`<span class="task-due">${due}</span>`:''}</div></article>`;}
function boardClick(e){const add=e.target.closest('#add-task');if(add){$('#task-form').reset();$('#task-error').textContent='';showDialog('task-dialog');return;}const card=e.target.closest('[data-task-id]');if(card)openTask(Number(card.dataset.taskId));}
$('#task-columns').addEventListener('click',boardClick);
$('#project-select').addEventListener('change',async e=>{const nextId=Number(e.target.value);if(nextId===state.projectId)return;state.projectId=nextId;setBoardTone(nextId);const shell=$('#board-view');shell.classList.add('project-switching');document.body.classList.remove('project-swishing');void document.body.offsetWidth;document.body.classList.add('project-swishing');setTimeout(()=>document.body.classList.remove('project-swishing'),680);await loadProject();requestAnimationFrame(()=>shell.classList.remove('project-switching'));});
$('#new-project').addEventListener('click',()=>{if(!state.user){setAuthMode('login');showDialog('auth-dialog');return;}$('#project-form').reset();$('#project-error').textContent='';showDialog('project-dialog');});
$('#share-project').addEventListener('click',()=>{if(!state.project)return;$('#member-error').textContent='';$('#member-form').reset();renderMembers();showDialog('members-dialog');});
function renderMembers(){ $('#member-list').innerHTML=state.members.map(m=>`<div class="member-row"><span class="task-assignee">${esc(m.name.split(/\s+/).map(part=>part[0]).slice(0,2).join('').toUpperCase())}</span><span><b>${esc(m.name)}</b><small>${esc(m.email)}</small></span><span class="member-role">${m.role==='owner'?'Owner':'Collaborator'}</span></div>`).join(''); }
$('#member-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;$('#member-error').textContent='';const email=new FormData(form).get('email');try{const data=await api(`/api/projects/${state.projectId}/members`,{method:'POST',body:JSON.stringify({email})});state.members=data.members;renderMembers();form.reset();await loadProject();toast('Your collaborator is on the project.');}catch(err){$('#member-error').textContent=err.message;}});
$('#project-form').addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.currentTarget);try{const data=await api('/api/projects',{method:'POST',body:JSON.stringify(Object.fromEntries(form.entries()))});state.projectId=data.project.id;closeDialog('project-dialog');await loadProjects();toast('A new space, ready for good work.');}catch(err){$('#project-error').textContent=err.message;}});
$('#task-form').addEventListener('submit',async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(e.currentTarget).entries());try{await api(`/api/projects/${state.projectId}/tasks`,{method:'POST',body:JSON.stringify(payload)});closeDialog('task-dialog');await loadProject();toast('A small step added to the board.');}catch(err){$('#task-error').textContent=err.message;}});
async function updateTask(id,patch){try{await api(`/api/projects/${state.projectId}/tasks/${id}`,{method:'PATCH',body:JSON.stringify(patch)});await loadProject();}catch(err){toast(err.message);}}
async function openTask(id){const task=state.tasks.find(t=>t.id===id);if(!task)return;state.activeTask=task;$('#detail-title').textContent=task.title;$('#detail-description').textContent=task.description||'No extra notes for this one yet.';$('#detail-meta').innerHTML=`<label class="task-status-control">Status <select id="task-status"><option value="todo" ${task.status==='todo'?'selected':''}>To do</option><option value="inprogress" ${task.status==='inprogress'?'selected':''}>In progress</option><option value="done" ${task.status==='done'?'selected':''}>Done</option></select></label><span>${esc(task.priority)} priority</span>${task.assignee?`<span>${esc(task.assignee)}</span>`:''}<button id="delete-task" class="delete-task">Delete task</button>`;$('#comment-list').innerHTML='<div class="comment-empty">Loading notes…</div>';showDialog('detail-dialog');
  try{const data=await api(`/api/projects/${state.projectId}/tasks/${id}/comments`);$('#comment-list').innerHTML=data.comments.length?data.comments.map(comment=>`<div class="comment-item"><span class="comment-author">${esc(comment.author)}</span><span class="comment-date">${new Date(`${comment.created_at.replace(' ','T')}Z`).toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</span><p class="comment-body">${esc(comment.body)}</p></div>`).join(''):'<div class="comment-empty">A fresh page. Leave the first note.</div>';}catch(err){$('#comment-list').textContent=err.message;}
  $('#task-status').addEventListener('change',async e=>{await updateTask(id,{status:e.target.value});state.activeTask=state.tasks.find(t=>t.id===id)||task;});
  $('#delete-task').addEventListener('click',async()=>{if(!window.confirm('Remove this task from the board?'))return;try{await api(`/api/projects/${state.projectId}/tasks/${id}`,{method:'DELETE'});closeDialog('detail-dialog');await loadProject();toast('Task removed.');}catch(err){toast(err.message);}});
}
$('#comment-form').addEventListener('submit',async e=>{e.preventDefault();if(!state.activeTask)return;const input=$('#comment-form [name="body"]');try{const data=await api(`/api/projects/${state.projectId}/tasks/${state.activeTask.id}/comments`,{method:'POST',body:JSON.stringify({body:input.value})});const c=data.comment;const item=document.createElement('div');item.className='comment-item';item.innerHTML=`<span class="comment-author">${esc(c.author)}</span><span class="comment-date">just now</span><p class="comment-body">${esc(c.body)}</p>`;$('#comment-list').append(item);input.value='';await loadProject();state.activeTask=state.tasks.find(t=>t.id===state.activeTask.id); }catch(err){toast(err.message);}});

// Open Room: encrypted room events, a shared sketch surface, and peer-to-peer WebRTC media.
const encoder = new TextEncoder();
const bytesToB64 = bytes => { let binary=''; for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000)); return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); };
const b64ToBytes = value => Uint8Array.from(atob(value.replace(/-/g,'+').replace(/_/g,'/')+'==='.slice((value.length+3)%4)),c=>c.charCodeAt(0));
function makeRoomKey(){const bytes=crypto.getRandomValues(new Uint8Array(32));return bytesToB64(bytes);}
async function importRoomKey(key){if(!key)throw new Error('This room needs its invite key. Ask the room owner for a fresh invite link.');return crypto.subtle.importKey('raw',b64ToBytes(key),'AES-GCM',false,['encrypt','decrypt']);}
async function encryptRoom(value){const roomKey=await importRoomKey(state.roomKey);const iv=crypto.getRandomValues(new Uint8Array(12));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},roomKey,encoder.encode(JSON.stringify(value)));return JSON.stringify({iv:bytesToB64(iv),data:bytesToB64(new Uint8Array(cipher))});}
async function decryptRoom(payload){const roomKey=await importRoomKey(state.roomKey);const envelope=JSON.parse(payload);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64ToBytes(envelope.iv)},roomKey,b64ToBytes(envelope.data));return JSON.parse(new TextDecoder().decode(plain));}
function roomApi(roomId,tail=''){return `/api/comms/rooms/${roomId}${tail}`;}
function roomStorageKey(roomId){return `openroom-key-${state.user?.id||'guest'}-${roomId}`;}
function getRoomKey(roomId){const scoped=localStorage.getItem(roomStorageKey(roomId));if(scoped)return scoped;const legacy=sessionStorage.getItem(`openroom-key-${roomId}`);if(legacy&&state.user){localStorage.setItem(roomStorageKey(roomId),legacy);sessionStorage.removeItem(`openroom-key-${roomId}`);return legacy;}return '';}
function saveRoomKey(roomId,key){localStorage.setItem(roomStorageKey(roomId),key);sessionStorage.removeItem(`openroom-key-${roomId}`);}
function forgetRoomKey(roomId){localStorage.removeItem(roomStorageKey(roomId));sessionStorage.removeItem(`openroom-key-${roomId}`);}
function renderRoomList(){ $('#room-count').textContent=String(state.rooms.length);$('#room-list').innerHTML=state.rooms.length?state.rooms.map(room=>{const selected=state.room?.id===room.id;const needsInvite=!getRoomKey(room.id);return `<div class="room-list-row"><button class="room-list-item ${selected?'selected':''}" data-room-id="${room.id}" aria-current="${selected?'true':'false'}"><span class="room-list-icon">◌</span><span class="room-list-copy"><b>${esc(room.name)}</b><small>${room.member_count} ${room.member_count===1?'person':'people'}${needsInvite?' · invite needed':''}</small></span><i class="room-state-dot" aria-hidden="true"></i></button>${room.is_owner?`<button class="room-delete-button" data-room-delete="${room.id}" aria-label="Delete ${esc(room.name)}" title="Delete room">Delete</button>`:''}</div>`;}).join(''):'<p class="room-list-empty">Your rooms will gather here.</p>';}
async function loadRooms(){if(!state.user){state.rooms=[];renderRoomList();return;}const data=await api('/api/comms/rooms');state.rooms=data.rooms;renderRoomList();}
function parseRoomInvite(value){const raw=String(value||'').trim();if(!raw)return {error:'Paste the full invite link shared by a room member.'};try{const url=new URL(raw,location.origin);const params=new URLSearchParams(url.hash.replace(/^#/,'').replace(/^\//,''));const code=params.get('talk')||'';const key=params.get('key')||'';if(code&&key)return {code,key};}catch{}return {error:/^[a-f0-9]{12}$/i.test(raw)?'A room code can add you to the room. Paste its private invite link here to open its encrypted content, or use the room-code field.':'That invite link does not look right. Ask a room member to copy a fresh invite link.'};}
function roomInviteParams(){return parseRoomInvite(location.href);}
async function handleRoomInvite(){if(state.roomInviteHandled||!state.user)return;const invite=roomInviteParams();if(!invite.code||!invite.key)return;state.roomInviteHandled=true;$('#room-invite').value=location.href;switchView('channel');await joinRoom(invite.code,invite.key);}
function roomErrorMessage(err){return err.message==='Not found.'?'This room action is missing from the server responding on localhost:3000. Stop any other copy of the app, then start it from the updated CodeAlpha_FullStackStudio folder.':err.message;}
async function joinRoom(code,key){$('#room-error').textContent='';if(!/^[A-Za-z0-9_-]{43}$/.test(key)){ $('#room-error').textContent='This invite is missing its private key. Paste the full invite link shared by a room member.';return;}try{const {room}=await api('/api/comms/rooms/join',{method:'POST',body:JSON.stringify({code})});saveRoomKey(room.id,key);await loadRooms();await openRoom(room,key);$('#room-invite').value='';history.replaceState(null,'',location.pathname+location.search+'#open-room');}catch(err){$('#room-error').textContent=roomErrorMessage(err);}}
async function joinRoomByCode(code){$('#room-error').textContent='';const normalized=String(code||'').trim().toLowerCase();if(!/^[a-f0-9]{12}$/.test(normalized)){ $('#room-error').textContent='Enter the 12-character room code.';return;}try{const {room}=await api('/api/comms/rooms/join',{method:'POST',body:JSON.stringify({code:normalized})});await loadRooms();$('#room-code').value='';const key=getRoomKey(room.id);if(key){await openRoom(room,key);toast(`You’re back in ${room.name}.`);}else toast(`Joined ${room.name}. Ask a room member for the private invite link to open its encrypted content.`);}catch(err){$('#room-error').textContent=roomErrorMessage(err);}}
function renderRoomPresence(){const people=[...state.roomPresence.values()];$('#room-members-count').textContent=`${String(people.length)} HERE`;$('#active-room-members').textContent=people.map(person=>person.name).join(' · ');const activity=people.filter(person=>person.activity&&Date.now()-person.activityAt<18000).map(person=>`${person.name} ${person.activity}`),text=activity.length?` · ${activity.join(' · ')}`:'';if($('#room-activity').textContent!==text)$('#room-activity').textContent=text;}
function renderRoomMembers(){const list=$('#room-member-list');if(!state.roomMembers.length){list.innerHTML='<p class="room-member-empty">No members found.</p>';return;}list.innerHTML=state.roomMembers.map(member=>{const owner=Number(member.id)===Number(state.roomOwnerId),self=Number(member.id)===Number(state.user?.id);return `<div class="room-member-row" role="listitem"><span class="room-member-avatar" aria-hidden="true">${esc(member.name.trim().split(/\s+/).map(word=>word[0]).slice(0,2).join('').toUpperCase())}</span><span class="room-member-copy"><b>${esc(member.name)}${self?' · you':''}</b><small>${owner?'OWNER':'MEMBER'}</small></span>${state.isRoomOwner&&!self?`<button type="button" class="room-member-kick" data-kick-member="${Number(member.id)}" aria-label="Remove ${esc(member.name)} from this room">Remove</button>`:''}</div>`;}).join('');}
async function loadRoomMembers(){if(!state.room)return;const data=await api(roomApi(state.room.id,'/members'));state.roomMembers=data.members;state.roomOwnerId=Number(data.owner_id);state.isRoomOwner=Number.isFinite(state.roomOwnerId)&&state.roomOwnerId===Number(state.user?.id);renderRoomMembers();}
function updateRoomPresence(event,data){const id=`${event.user_id}:${data.clientId||'browser'}`;if(Number(event.user_id)===Number(state.user?.id)&&data.clientId===state.callClientId)return;const existing=state.roomPresence.get(id);if(data.action==='leave'){if(existing){state.roomPresence.delete(id);toast(`${existing.name} left the room.`);}renderRoomPresence();return;}const person={id,userId:Number(event.user_id),clientId:data.clientId||'browser',name:event.author||'Room guest',seenAt:Date.now(),activity:existing?.activity||'',activityAt:existing?.activityAt||0};if(!existing&&data.action==='join')toast(`${person.name} joined the room.`);if(Object.hasOwn(data,'activity')){person.activity=data.activity||'';person.activityAt=data.activity?Date.now():0;}state.roomPresence.set(id,person);renderRoomPresence();}
function sendRoomPresence(action='heartbeat',extra={}){if(!state.room)return;sendSignal(null,{type:'room-presence',clientId:state.callClientId,action,...extra}).catch(()=>{});}
function startRoomPresence(){clearInterval(state.presenceTimer);state.roomActivity='';state.roomPresence=new Map([[`${state.user?.id}:${state.callClientId}`,{id:`${state.user?.id}:${state.callClientId}`,userId:Number(state.user?.id),clientId:state.callClientId,name:state.user?.name||'You',seenAt:Date.now()}]]);renderRoomPresence();sendRoomPresence('join');state.presenceTimer=setInterval(()=>{sendRoomPresence('heartbeat',{activity:state.roomActivity});const own=state.roomPresence.get(`${state.user?.id}:${state.callClientId}`);if(own&&state.roomActivity)own.activityAt=Date.now();for(const [id,person] of state.roomPresence)if(id!==`${state.user?.id}:${state.callClientId}`&&Date.now()-person.seenAt>42000){state.roomPresence.delete(id);toast(`${person.name} left the room.`);}renderRoomPresence();},15000);}
async function closeRoom(){if(state.room)sendRoomPresence('leave');clearInterval(state.presenceTimer);state.presenceTimer=null;state.roomPresence.clear();clearTimeout(boardSyncTimer);state.drawing=false;state.roomStreamController?.abort();state.roomStreamController=null;state.roomStreamReady=null;await leaveCall(false);state.room=null;state.roomKey=null;state.roomAfter=0;state.boardUndo=[];state.roomFiles.clear();state.roomMembers=[];state.roomOwnerId=null;state.isRoomOwner=false;$('#room-active').classList.add('hidden');$('#room-empty').classList.remove('hidden');$('#room-error').textContent='';clearWhiteboard();renderRoomList();}
async function openRoom(room,key=''){if(state.room)sendRoomPresence('leave');clearInterval(state.presenceTimer);state.presenceTimer=null;clearTimeout(boardSyncTimer);state.drawing=false;state.roomStreamController?.abort();state.roomStreamReady=null;await leaveCall(false);state.room=room;state.roomKey=key||getRoomKey(room.id);state.roomMembers=[];state.roomOwnerId=null;state.isRoomOwner=false;state.roomAfter=0;state.boardUndo=[];state.roomFiles.clear();$('#room-empty').classList.add('hidden');$('#room-active').classList.remove('hidden');$('#active-room-name').textContent=room.name;$('#active-room-code').textContent=room.code;$('#chat-log').innerHTML='<div class="chat-welcome">A fresh page. Say hello.</div>';$('#chat-count').textContent='0';clearWhiteboard();renderRoomList();try{await loadRoomMembers();}catch{}startRoomStream();startRoomPresence();}
$('#room-list').addEventListener('click',e=>{const remove=e.target.closest('[data-room-delete]');if(remove){const room=state.rooms.find(item=>item.id===Number(remove.dataset.roomDelete));if(!room)return;if(!window.confirm(`Delete “${room.name}” permanently? This removes the room and its encrypted messages for everyone.`))return;remove.disabled=true;api(roomApi(room.id),{method:'DELETE'}).then(async()=>{forgetRoomKey(room.id);if(state.room?.id===room.id)await closeRoom();await loadRooms();toast('Room deleted.');}).catch(err=>{remove.disabled=false;toast(err.message);});return;}const button=e.target.closest('[data-room-id]');if(!button)return;const room=state.rooms.find(item=>item.id===Number(button.dataset.roomId));if(!room)return;const key=getRoomKey(room.id);if(!key){toast('This browser has no saved invite key for that room. Paste a member’s private invite link, or delete and recreate it if you own it.');return;}openRoom(room,key).catch(err=>toast(err.message));});
$('#room-create-form').addEventListener('submit',async e=>{e.preventDefault();if(!state.user)return;const form=e.currentTarget;const name=new FormData(form).get('name');const key=makeRoomKey();$('#room-error').textContent='';try{const {room}=await api('/api/comms/rooms',{method:'POST',body:JSON.stringify({name})});saveRoomKey(room.id,key);form.reset();await loadRooms();await openRoom(room,key);toast('Room is ready. Copy its invite to bring people in.');}catch(err){$('#room-error').textContent=roomErrorMessage(err);}});
$('#room-join-form').addEventListener('submit',async e=>{e.preventDefault();const invite=parseRoomInvite(new FormData(e.currentTarget).get('invite'));if(invite.error){$('#room-error').textContent=invite.error;return;}await joinRoom(invite.code,invite.key);});
$('#room-code-form').addEventListener('submit',async e=>{e.preventDefault();await joinRoomByCode(new FormData(e.currentTarget).get('code'));});
$('#close-room').addEventListener('click',closeRoom);
async function sendRoomEvent(kind,value,encrypted=true){if(!state.room)throw new Error('Choose a room first.');const payload=encrypted?await encryptRoom(value):JSON.stringify(value);return api(roomApi(state.room.id,'/events'),{method:'POST',body:JSON.stringify({kind,payload})});}
function addChatMessage(event,value){if(!value)return;const log=$('#chat-log');if(log.querySelector('.chat-welcome'))log.innerHTML='';const mine=event.user_id===state.user?.id;const row=document.createElement('article');row.className=`chat-message ${mine?'mine':''}`;row.innerHTML=`<header><b>${mine?'You':esc(event.author)}</b><time>${new Date(`${event.created_at.replace(' ','T')}Z`).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})}</time></header>${event.kind==='file'?`<div class="shared-file"><span>↗</span><div><b>${esc(value.name)}</b><small>${Math.max(1,Math.round(value.size/1024))} KB · private file</small></div><button type="button" data-room-file="${event.id}">Save</button></div>`:`<p>${esc(value.text||'').replace(/\n/g,'<br>')}</p>`}`;log.append(row);log.scrollTop=log.scrollHeight;if(event.kind==='file')state.roomFiles.set(event.id,value);const n=log.querySelectorAll('.chat-message').length;$('#chat-count').textContent=String(n);}
function setWhiteboardImage(image,roomId=state.room?.id){if(!image)return;const img=new Image();img.onload=()=>{if(!state.room||state.room.id!==roomId)return;const canvas=$('#whiteboard');const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.globalCompositeOperation='source-over';ctx.drawImage(img,0,0,canvas.width,canvas.height);};img.src=image;}
async function handleRoomEvent(event,roomId=state.room?.id){if(event.room_deleted){if(state.room?.id===roomId){toast('This room was deleted by its owner.');closeDialog('room-members-dialog');await closeRoom();await loadRooms();}return;}if(!state.room||state.room.id!==roomId)return;if(event.room_removed){if(Number(event.user_id)===Number(state.user?.id)){toast(event.reason==='left'?'You left the room.':'You were removed from this room.');closeDialog('room-members-dialog');await closeRoom();await loadRooms();return;}const removed=state.roomMembers.find(member=>Number(member.id)===Number(event.user_id));for(const [presenceId,person] of state.roomPresence)if(Number(person.userId)===Number(event.user_id))state.roomPresence.delete(presenceId);for(const [peerId,peer] of state.peers)if(Number(peer.remote.userId)===Number(event.user_id))removePeer(peerId);renderRoomPresence();await loadRoomMembers().catch(()=>{});toast(`${event.author||removed?.name||'A member'} ${event.reason==='kicked'?'was removed from':'left'} the room.`);return;}if(event.room_code_rotated){state.room.code=event.code;$('#active-room-code').textContent=event.code;const saved=state.rooms.find(room=>room.id===state.room.id);if(saved)saved.code=event.code;toast('The room code changed. Use Copy code or copy a fresh invite link.');return;}if(event.room_owner_changed){state.roomOwnerId=Number(event.owner_id);state.isRoomOwner=state.roomOwnerId===Number(state.user?.id);renderRoomMembers();if(state.isRoomOwner)toast('You are now the room owner.');return;}if(event.kind==='stream-ready'){if(state.roomStreamReady?.roomId===roomId)state.roomStreamReady.resolve();return;}if(event.kind==='signal'){await handleSignal(event);return;}if(event.id<=state.roomAfter)return;state.roomAfter=event.id;try{const value=await decryptRoom(event.payload);if(event.kind==='message'||event.kind==='file')addChatMessage(event,value);else if(event.kind==='board'&&event.user_id!==state.user?.id)setWhiteboardImage(value.image);}catch{if(event.user_id!==state.user?.id)toast('An item could not be opened. Check that you have the latest room invite key.');}}
function startRoomStream(){const roomId=state.room?.id;if(!roomId)return;let resolveReady;const ready=new Promise(resolve=>{resolveReady=resolve;});state.roomStreamReady={roomId,promise:ready,resolve:resolveReady};const controller=new AbortController();state.roomStreamController=controller;(async()=>{let delay=500;while(!controller.signal.aborted&&state.room?.id===roomId){try{const response=await fetch(roomApi(roomId,`/stream?after=${state.roomAfter}`),{headers:{Authorization:`Bearer ${state.token}`},signal:controller.signal});if(response.status===401){await signOut(false);return;}if(!response.ok)throw new Error('Room connection paused. Reconnect to continue.');const reader=response.body.getReader();const decoder=new TextDecoder();let buffer='';while(!controller.signal.aborted){const {value,done}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});const lines=buffer.split('\n');buffer=lines.pop()||'';for(const line of lines)if(line.startsWith('data: ')){try{await handleRoomEvent(JSON.parse(line.slice(6)),roomId);}catch(err){if(err instanceof SyntaxError)console.warn('A room event could not be read.');}}if(done)break;}delay=350;}catch(err){if(controller.signal.aborted)return;console.warn('Room stream reconnecting',err.message);}if(!controller.signal.aborted&&state.room?.id===roomId){await new Promise(resolve=>setTimeout(resolve,delay));delay=Math.min(delay*2,5000);}}})().catch(err=>console.warn('Room connection stopped',err));}
$('#chat-form').addEventListener('submit',async e=>{e.preventDefault();const input=$('#chat-form [name="body"]');const text=input.value.trim();if(!text)return;try{await sendRoomEvent('message',{text});input.value='';}catch(err){toast(err.message);}});
$('#file-pick').addEventListener('click',()=>$('#file-input').click());
$('#file-input').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>700*1024){toast('Keep shared files under 700 KB for now.');e.target.value='';return;}try{const data=bytesToB64(new Uint8Array(await file.arrayBuffer()));await sendRoomEvent('file',{name:file.name,type:file.type||'application/octet-stream',size:file.size,data});toast('Encrypted file sent.');}catch(err){toast(err.message);}finally{e.target.value='';}});
$('#chat-log').addEventListener('click',e=>{const button=e.target.closest('[data-room-file]');if(!button)return;const file=state.roomFiles.get(Number(button.dataset.roomFile));if(!file)return;const blob=new Blob([b64ToBytes(file.data)],{type:file.type});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=file.name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);});
$('#invite-room').addEventListener('click',async()=>{if(!state.room||!state.roomKey)return;const url=`${location.origin}${location.pathname}#talk=${encodeURIComponent(state.room.code)}&key=${encodeURIComponent(state.roomKey)}`;try{await navigator.clipboard.writeText(url);toast('Private room invite copied.');}catch{window.prompt('Copy this private invite link:',url);}});
$('#copy-room-code').addEventListener('click',async()=>{if(!state.room)return;try{await navigator.clipboard.writeText(state.room.code);toast('Room code copied.');}catch{window.prompt('Copy this room code:',state.room.code);}});
$('#manage-room-members').addEventListener('click',async()=>{if(!state.room)return;$('#room-members-error').textContent='';try{await loadRoomMembers();showDialog('room-members-dialog');}catch(err){$('#room-members-error').textContent=err.message;showDialog('room-members-dialog');}});
$('#room-member-list').addEventListener('click',async e=>{const button=e.target.closest('[data-kick-member]');if(!button||!state.room||!state.isRoomOwner)return;const member=state.roomMembers.find(item=>Number(item.id)===Number(button.dataset.kickMember));if(!member)return;if(!window.confirm(`Remove ${member.name} from this room? The room code will change, so old invite links stop working. Share a fresh link with the remaining members.`))return;button.disabled=true;$('#room-members-error').textContent='';try{const result=await api(roomApi(state.room.id,`/members/${member.id}`),{method:'DELETE'});state.room.code=result.room.code;$('#active-room-code').textContent=result.room.code;await loadRoomMembers();await loadRooms();toast(`${member.name} removed. The new code and invite link are ready to share.`);}catch(err){button.disabled=false;$('#room-members-error').textContent=roomErrorMessage(err);}});
$('#leave-room').addEventListener('click',async()=>{if(!state.room)return;const warning=state.isRoomOwner?'Leave this room? Ownership will move to the longest-standing remaining member. If you are the only member, the room will be deleted.':'Leave this room? You will need a room code or invite link to join again.';if(!window.confirm(warning))return;const oldRoomName=state.room.name;try{const result=await api(roomApi(state.room.id,'/leave'),{method:'POST',body:JSON.stringify({})});closeDialog('room-members-dialog');await closeRoom();await loadRooms();if(result.deleted)toast(`${oldRoomName} was deleted because you were the last member.`);else if(result.transferredTo)toast(`You left ${oldRoomName}. Ownership passed to ${result.transferredTo.name}.`);else toast(`You left ${oldRoomName}.`);}catch(err){$('#room-members-error').textContent=roomErrorMessage(err);}});
$$('.room-tab').forEach(button=>button.addEventListener('click',()=>{$$('.room-tab').forEach(tab=>tab.classList.toggle('active',tab===button));$$('.room-panel').forEach(panel=>panel.classList.toggle('active',panel.id===`room-${button.dataset.roomTab}-panel`));}));
const whiteboard=$('#whiteboard');
let boardSyncTimer;
function rememberBoard(){const ctx=whiteboard.getContext('2d');state.boardUndo.push(ctx.getImageData(0,0,whiteboard.width,whiteboard.height));if(state.boardUndo.length>8)state.boardUndo.shift();$('#undo-board').disabled=false;}
function clearWhiteboard(){const context=whiteboard.getContext('2d');context.clearRect(0,0,whiteboard.width,whiteboard.height);context.globalCompositeOperation='source-over';}
function boardPoint(event){const rect=whiteboard.getBoundingClientRect();return {x:(event.clientX-rect.left)*whiteboard.width/rect.width,y:(event.clientY-rect.top)*whiteboard.height/rect.height};}
async function syncWhiteboard(){if(!state.room)return;clearTimeout(boardSyncTimer);boardSyncTimer=setTimeout(async()=>{state.boardLastSent=Date.now();try{await sendRoomEvent('board',{image:whiteboard.toDataURL('image/webp',.78)});}catch(err){toast(err.message);}},220);}
function updateBoardToolState(){ $$('.board-swatch').forEach(button=>{const selected=!state.boardEraser&&button.dataset.boardColor===state.boardColor;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));});$('#board-eraser').classList.toggle('active',state.boardEraser);$('#board-eraser').setAttribute('aria-pressed',String(state.boardEraser));$$('[data-board-mode]').forEach(button=>{const selected=button.dataset.boardMode===state.boardMode;button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected));});$('#undo-board').disabled=!state.boardUndo.length; }
$$('.board-swatch').forEach(button=>button.addEventListener('click',()=>{state.boardColor=button.dataset.boardColor;state.boardEraser=false;$('#board-color').value=state.boardColor;updateBoardToolState();}));
$('#board-color').addEventListener('input',event=>{state.boardColor=event.target.value;state.boardEraser=false;updateBoardToolState();});
$('#board-size').addEventListener('input',event=>{state.boardSize=Number(event.target.value);$('#board-size-value').value=String(state.boardSize);$('#board-size-value').textContent=String(state.boardSize);});
$('#board-eraser').addEventListener('click',()=>{state.boardEraser=!state.boardEraser;updateBoardToolState();});
$$('[data-board-mode]').forEach(button=>button.addEventListener('click',()=>{state.boardMode=button.dataset.boardMode;state.boardEraser=false;whiteboard.setAttribute('data-tool',state.boardMode);updateBoardToolState();}));
$('#undo-board').addEventListener('click',async()=>{const previous=state.boardUndo.pop();if(!previous)return;whiteboard.getContext('2d').putImageData(previous,0,0);updateBoardToolState();await syncWhiteboard();});
function drawBoardShape(ctx,start,end){ctx.beginPath();if(state.boardMode==='line'){ctx.moveTo(start.x,start.y);ctx.lineTo(end.x,end.y);}else if(state.boardMode==='rectangle'){ctx.rect(start.x,start.y,end.x-start.x,end.y-start.y);}else if(state.boardMode==='circle'){const radius=Math.hypot(end.x-start.x,end.y-start.y);ctx.arc(start.x,start.y,radius,0,Math.PI*2);}ctx.stroke();}
function announceRoomActivity(activity){state.roomActivity=activity;const own=state.roomPresence.get(`${state.user?.id}:${state.callClientId}`);if(own){own.activity=activity;own.activityAt=activity?Date.now():0;renderRoomPresence();}sendRoomPresence('heartbeat',{activity});}
whiteboard.addEventListener('pointerdown',e=>{if(!state.room)return;const point=boardPoint(e);if(state.boardMode==='text'){const label=window.prompt('Text to place on the board:');if(!label)return;rememberBoard();const ctx=whiteboard.getContext('2d');ctx.globalCompositeOperation='source-over';ctx.fillStyle=state.boardColor;ctx.font=`${Math.max(16,state.boardSize*4)}px 'DM Sans', sans-serif`;ctx.textBaseline='top';ctx.fillText(label.slice(0,120),point.x,point.y,Math.max(100,whiteboard.width-point.x));announceRoomActivity('is adding a label');syncWhiteboard();setTimeout(()=>announceRoomActivity(''),2500);return;}rememberBoard();state.drawing=true;state.boardStart=point;state.boardPreview=whiteboard.getContext('2d').getImageData(0,0,whiteboard.width,whiteboard.height);whiteboard.setPointerCapture(e.pointerId);const ctx=whiteboard.getContext('2d');ctx.lineCap='round';ctx.lineJoin='round';ctx.globalCompositeOperation=state.boardEraser?'destination-out':'source-over';ctx.strokeStyle=state.boardColor;ctx.lineWidth=state.boardSize;if(state.boardMode==='pen'||state.boardEraser){ctx.beginPath();ctx.moveTo(point.x,point.y);}announceRoomActivity('is drawing');});
whiteboard.addEventListener('pointermove',e=>{if(!state.drawing)return;const point=boardPoint(e),ctx=whiteboard.getContext('2d');if(state.boardMode==='pen'||state.boardEraser){ctx.lineTo(point.x,point.y);ctx.stroke();}else{ctx.putImageData(state.boardPreview,0,0);ctx.globalCompositeOperation='source-over';ctx.strokeStyle=state.boardColor;ctx.lineWidth=state.boardSize;drawBoardShape(ctx,state.boardStart,point);}});
function finishBoardStroke(){if(!state.drawing)return;state.drawing=false;state.boardPreview=null;whiteboard.getContext('2d').globalCompositeOperation='source-over';announceRoomActivity('');syncWhiteboard();}
whiteboard.addEventListener('pointerup',finishBoardStroke);whiteboard.addEventListener('pointercancel',finishBoardStroke);
$('#clear-board').addEventListener('click',async()=>{if(!state.room)return;if(!window.confirm('Clear the shared whiteboard for everyone in this room? You can undo it afterward.'))return;rememberBoard();clearWhiteboard();updateBoardToolState();await syncWhiteboard();});
updateBoardToolState();
function callPeerKey(userId,clientId){return `${Number(userId)}-${String(clientId)}`;}
function localCallPeerIsOfferer(remote){return state.user.id<remote.userId||state.user.id===remote.userId&&state.callClientId<remote.clientId;}
async function sendSignal(to,data){if(!state.room)return;const payload={fromClientId:state.callClientId,toClientId:to?.clientId||null,sentAt:Date.now(),data};await api(roomApi(state.room.id,'/signals'),{method:'POST',body:JSON.stringify({payload})});}
function publishMediaState(){for(const peer of state.peers.values())sendSignal(peer.remote,{type:'media-state',camera:state.cameraEnabled,sharing:Boolean(state.screenStream),microphone:state.microphoneEnabled}).catch(()=>{});}
function updateRemoteMedia(peerId,name,media={}){let tile=$(`#remote-${peerId}`);if(!tile){tile=document.createElement('div');tile.className='video-tile camera-off';tile.id=`remote-${peerId}`;tile.innerHTML=`<video autoplay muted playsinline></video><audio autoplay></audio><span></span><button type="button" class="media-play-button hidden">Tap to hear</button>`;tile.querySelector('.media-play-button').addEventListener('click',()=>tile.querySelector('audio').play().then(()=>tile.querySelector('.media-play-button').classList.add('hidden')).catch(()=>{}));$('#video-grid').append(tile);}tile.dataset.camera=String(Boolean(media.camera));tile.dataset.sharing=String(Boolean(media.sharing));tile.dataset.microphone=String(Boolean(media.microphone));const videoOn=Boolean(media.camera||media.sharing);tile.classList.toggle('camera-off',!videoOn);tile.querySelector('span').textContent=`${name} · ${media.sharing?'sharing screen':`camera ${media.camera?'on':'off'}`} · mic ${media.microphone?'on':'off'}`;return tile;}
function makePeer(remote){const key=callPeerKey(remote.userId,remote.clientId);if(state.peers.has(key))return state.peers.get(key);const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});const peer={pc,remote,name:remote.name,queuedIce:[],audioSender:null,videoSender:null,remoteStream:new MediaStream()};state.peers.set(key,peer);pc.onicecandidate=event=>{if(event.candidate)sendSignal(remote,{type:'candidate',candidate:event.candidate.toJSON()}).catch(()=>{});};pc.ontrack=event=>{const existing=document.getElementById(`remote-${key}`),media={camera:existing?.dataset.camera==null?event.track.kind==='video':existing.dataset.camera==='true',sharing:existing?.dataset.sharing==='true',microphone:existing?.dataset.microphone==null?event.track.kind==='audio':existing.dataset.microphone==='true'},tile=updateRemoteMedia(key,remote.name,media);if(!peer.remoteStream.getTracks().some(track=>track.id===event.track.id))peer.remoteStream.addTrack(event.track);const video=tile.querySelector('video'),audio=tile.querySelector('audio');video.srcObject=peer.remoteStream;audio.srcObject=peer.remoteStream;video.play().catch(()=>{});audio.play().then(()=>tile.querySelector('.media-play-button').classList.add('hidden')).catch(()=>tile.querySelector('.media-play-button').classList.remove('hidden'));};pc.onconnectionstatechange=()=>{if(pc.connectionState==='connected'){state.callConnectionIssue='';updateCallControls();}else if(pc.connectionState==='failed'){state.callConnectionIssue='The browsers could not connect. Check that both are online and try leaving and rejoining the call.';updateCallControls();removePeer(key);}else if(pc.connectionState==='closed')removePeer(key);else updateCallControls();};return peer;}
async function preparePeerSenders(peer){const transceiverFor=kind=>peer.pc.getTransceivers().find(item=>item.receiver.track.kind===kind)||peer.pc.addTransceiver(kind,{direction:'sendrecv'});const audio=transceiverFor('audio'),video=transceiverFor('video');audio.direction='sendrecv';video.direction='sendrecv';peer.audioSender=audio.sender;peer.videoSender=video.sender;const audioTrack=state.microphoneEnabled?state.localStream?.getAudioTracks()[0]||null:null,videoTrack=state.cameraEnabled?state.localStream?.getVideoTracks()[0]||null:null;await Promise.all([peer.audioSender.replaceTrack(audioTrack),peer.videoSender.replaceTrack(state.screenStream?.getVideoTracks()[0]||videoTrack)]);}
async function createOffer(remote){const peer=makePeer(remote);await preparePeerSenders(peer);const offer=await peer.pc.createOffer();await peer.pc.setLocalDescription(offer);await sendSignal(remote,{type:'offer',description:peer.pc.localDescription});await sendSignal(remote,{type:'media-state',camera:state.cameraEnabled,sharing:Boolean(state.screenStream),microphone:state.microphoneEnabled}).catch(()=>{});}
async function handleSignal(event){if(!state.room)return;let packet;try{packet=typeof event.payload==='string'?JSON.parse(event.payload):event.payload;}catch{return;}if(!packet.fromClientId&&(Number(event.user_id)===Number(state.user?.id)||Number(packet.to)!==Number(state.user?.id)))return;const fromClientId=packet.fromClientId||`legacy-${event.user_id}`;if(fromClientId===state.callClientId||packet.toClientId&&packet.toClientId!==state.callClientId)return;const remote={userId:Number(event.user_id),clientId:String(fromClientId),name:event.author||'Room guest'},key=callPeerKey(remote.userId,remote.clientId),data=packet.data||{};if(data.type==='room-presence'){updateRoomPresence(event,data);return;}if(data.type==='hello'){if(!state.callJoined){state.callJoined=true;updateCallControls();}if(!data.reply)sendSignal(remote,{type:'hello',reply:true}).catch(()=>{});if(localCallPeerIsOfferer(remote)&&!state.peers.has(key)){try{await createOffer(remote);}catch(err){console.warn('Call offer could not be created',err);}}return;}if(data.type==='media-state'){updateRemoteMedia(key,remote.name,data);return;}if(data.type==='bye'){removePeer(key);return;}if(!state.callJoined&&data.type!=='offer')return;const peer=makePeer(remote);try{if(data.type==='offer'){await peer.pc.setRemoteDescription(data.description);await preparePeerSenders(peer);for(const candidate of peer.queuedIce.splice(0))await peer.pc.addIceCandidate(candidate);state.callJoined=true;updateCallControls();const answer=await peer.pc.createAnswer();await peer.pc.setLocalDescription(answer);await sendSignal(remote,{type:'answer',description:peer.pc.localDescription});await sendSignal(remote,{type:'media-state',camera:state.cameraEnabled,sharing:Boolean(state.screenStream),microphone:state.microphoneEnabled}).catch(()=>{});}else if(data.type==='answer'){await peer.pc.setRemoteDescription(data.description);for(const candidate of peer.queuedIce.splice(0))await peer.pc.addIceCandidate(candidate);}else if(data.type==='candidate'){const candidate=new RTCIceCandidate(data.candidate);if(peer.pc.remoteDescription)await peer.pc.addIceCandidate(candidate);else peer.queuedIce.push(candidate);}}catch(err){console.warn('Call connection could not be negotiated',err);}}
function removePeer(peerId){const key=String(peerId),peer=state.peers.get(key);if(!peer)return;peer.pc.close();state.peers.delete(key);document.getElementById(`remote-${key}`)?.remove();updateCallControls();}
function updateCallControls(){const mic=$('#microphone-toggle'),camera=$('#camera-toggle');mic.textContent=state.microphoneEnabled?'Mute mic':'Enable mic';mic.setAttribute('aria-pressed',String(state.microphoneEnabled));mic.classList.toggle('is-active',state.microphoneEnabled);camera.textContent=state.cameraEnabled?'Turn camera off':'Enable camera';camera.setAttribute('aria-pressed',String(state.cameraEnabled));camera.classList.toggle('is-active',state.cameraEnabled);$('#screen-share').textContent=state.screenStream?'Stop sharing':'Share screen';$('#screen-share').setAttribute('aria-pressed',String(Boolean(state.screenStream)));$('#screen-share').classList.toggle('is-active',Boolean(state.screenStream));$('#end-call').classList.toggle('hidden',!state.callJoined);if(state.callJoined){const parts=[state.microphoneEnabled?'mic on':'mic off',state.cameraEnabled?'camera on':'camera off'];const links=[...state.peers.values()].map(peer=>peer.pc.connectionState);const linkStatus=links.includes('connected')?'Connected to room':links.some(status=>['new','connecting'].includes(status))?'Connecting to another person':links.length?'Waiting for another person':'Waiting for another person';$('#call-status').textContent=state.callConnectionIssue||`In the room call · ${parts.join(' · ')}${state.screenStream?' · sharing screen':''} · ${linkStatus}`;}else $('#call-status').textContent='Turn on your mic or camera when you’re ready.';}
function mediaErrorMessage(err,device){if(err.name==='NotAllowedError'||err.name==='SecurityError')return `Access to your ${device} was blocked. Allow it in this browser's site permissions, then check Windows privacy settings if it still fails. Incognito has separate permissions.`;if(err.name==='NotFoundError')return `No ${device} was found. Connect or enable one in Windows settings and try again.`;if(err.name==='NotReadableError'||err.name==='AbortError')return `Your ${device} is busy or unavailable. Close other apps or browser tabs using it, then retry.`;if(err.name==='OverconstrainedError')return `The selected ${device} cannot use the requested settings. Choose another device and try again.`;if(!window.isSecureContext)return `The browser only allows ${device} access on localhost or a secure HTTPS page.`;return `Could not enable ${device}: ${err.message}`;}
async function updateSpeechMonitor(){const track=state.localStream?.getAudioTracks().find(item=>item.readyState==='live');if(!state.microphoneEnabled||!track){clearInterval(state.speechTimer);state.speechTimer=null;await state.speechContext?.close().catch(()=>{});state.speechContext=null;if(state.callSpeaking){state.callSpeaking=false;announceRoomActivity('');}return;}if(state.speechTimer||!window.AudioContext)return;try{const context=new AudioContext(),analyser=context.createAnalyser(),source=context.createMediaStreamSource(new MediaStream([track])),muted=context.createGain();analyser.fftSize=512;muted.gain.value=0;source.connect(analyser);analyser.connect(muted);muted.connect(context.destination);await context.resume();state.speechContext=context;const samples=new Uint8Array(analyser.fftSize);state.speechTimer=setInterval(()=>{analyser.getByteTimeDomainData(samples);let total=0;for(const value of samples){const delta=(value-128)/128;total+=delta*delta;}const speaking=Math.sqrt(total/samples.length)>.035;if(speaking!==state.callSpeaking){state.callSpeaking=speaking;announceRoomActivity(speaking?'is speaking':'');}},350);}catch(err){console.debug('Speaking indicator unavailable',err);}}
async function checkCallConnection(){if(!state.room){toast('Open a room first to check its connection.');return;}if(!state.peers.size){$('#call-status').textContent=state.callJoined?'Waiting for another person to join. Your room connection is open.':'No one else is connected to the call yet. Turn on your mic or camera to join.';return;}try{const reports=await Promise.all([...state.peers.values()].map(peer=>peer.pc.getStats()));const peers=[...state.peers.values()];const metrics=reports.map((report,index)=>{let rtt=null,received=0,sent=0;report.forEach(item=>{if(item.type==='candidate-pair'&&(item.selected||item.nominated&&item.state==='succeeded'))rtt=item.currentRoundTripTime;if(item.type==='inbound-rtp')received+=item.bytesReceived||0;if(item.type==='outbound-rtp')sent+=item.bytesSent||0;});return {name:peers[index].name,state:peers[index].pc.connectionState,rtt,received,sent};});const healthy=metrics.filter(item=>item.state==='connected').length;$('#call-status').textContent=metrics.map(item=>`${item.name}: ${item.state}${item.rtt!=null?` · ${Math.round(item.rtt*1000)} ms round trip`:''}${item.received+item.sent===0?' · no media received yet':''}`).join(' | ')+(healthy===metrics.length?' · Connection looks good.':' · Check that both devices are online and have allowed browser access.');}catch(err){$('#call-status').textContent=`Could not read connection details: ${err.message}`;}}
function updateLocalPreview(){const tile=$('.local-tile'),video=$('#local-video');if(state.screenStream){video.srcObject=state.screenStream;tile.classList.add('has-stream');$('#local-video-name').textContent='You · sharing screen';video.play().catch(()=>{});return;}if(state.cameraEnabled&&state.localStream?.getVideoTracks().some(track=>track.readyState==='live')){video.srcObject=state.localStream;tile.classList.add('has-stream');$('#local-video-name').textContent=`${state.user?.name||'You'} · camera on`;video.play().catch(()=>{});return;}video.pause();video.srcObject=null;video.removeAttribute('src');video.load();tile.classList.remove('has-stream');$('#local-video-name').textContent=`${state.user?.name||'You'} · camera off${state.microphoneEnabled?' · mic on':''}`;}
async function ensureCall(){if(state.callJoined)return;if(state.callStarting)return state.callStarting;if(!state.room)throw new Error('Open a room before starting a call.');state.callStarting=(async()=>{try{const stream=state.roomStreamReady;if(!stream||stream.roomId!==state.room.id)throw new Error('The room connection is still opening. Try again in a moment.');let timeout;try{await Promise.race([stream.promise,new Promise((_,reject)=>{timeout=setTimeout(()=>reject(new Error('The room connection is taking too long. Reopen the room and try again.')),8000);})]);}finally{clearTimeout(timeout);}state.callJoined=true;updateCallControls();await sendSignal(null,{type:'hello'});}catch(err){state.callJoined=false;updateCallControls();throw err;}finally{state.callStarting=null;}})();return state.callStarting;}
async function setMediaEnabled(kind,enabled){const isAudio=kind==='audio',enabledKey=isAudio?'microphoneEnabled':'cameraEnabled';if(enabled===state[enabledKey])return;if(enabled){await ensureCall();let track=(isAudio?state.localStream?.getAudioTracks():state.localStream?.getVideoTracks())?.find(item=>item.readyState==='live');if(!track){const capture=await navigator.mediaDevices.getUserMedia({audio:isAudio,video:!isAudio});track=isAudio?capture.getAudioTracks()[0]:capture.getVideoTracks()[0];if(!state.localStream)state.localStream=new MediaStream();for(const old of (isAudio?state.localStream.getAudioTracks():state.localStream.getVideoTracks())){state.localStream.removeTrack(old);old.stop();}state.localStream.addTrack(track);track.onended=()=>{if((isAudio?state.microphoneEnabled:state.cameraEnabled)){state[enabledKey]=false;updateCallControls();updateLocalPreview();publishMediaState();}};}track.enabled=true;state[enabledKey]=true;const shareVideo=isAudio?null:state.screenStream?.getVideoTracks()[0];await Promise.all([...state.peers.values()].map(peer=>{const sender=isAudio?peer.audioSender:peer.videoSender;return sender?sender.replaceTrack(shareVideo||track):Promise.resolve();}));}else{state[enabledKey]=false;const track=(isAudio?state.localStream?.getAudioTracks():state.localStream?.getVideoTracks())?.[0];if(track)track.enabled=false;if(!isAudio&&!state.screenStream)await Promise.all([...state.peers.values()].map(peer=>peer.videoSender?.replaceTrack(null)));}updateCallControls();updateLocalPreview();publishMediaState();updateSpeechMonitor();}
async function stopScreenShare(){const stream=state.screenStream;if(!stream)return;state.screenStream=null;for(const track of stream.getTracks())track.stop();const cameraTrack=state.cameraEnabled?state.localStream?.getVideoTracks().find(track=>track.readyState==='live')||null:null;await Promise.all([...state.peers.values()].map(peer=>peer.videoSender?peer.videoSender.replaceTrack(cameraTrack).catch(()=>{}):Promise.resolve()));updateCallControls();updateLocalPreview();publishMediaState();}
async function toggleScreenShare(){if(state.screenStream){await stopScreenShare();return;}let stream;try{if(!window.isSecureContext||!navigator.mediaDevices?.getDisplayMedia)throw new Error('Screen sharing needs localhost or an HTTPS page and a browser that supports screen capture.');stream=await navigator.mediaDevices.getDisplayMedia({video:true});const track=stream.getVideoTracks()[0];if(!track){stream.getTracks().forEach(item=>item.stop());return;}state.screenStream=stream;track.onended=()=>{if(state.screenStream===stream)stopScreenShare().catch(err=>console.warn('Could not restore camera after screen sharing',err));};await ensureCall();await Promise.all([...state.peers.values()].map(peer=>peer.videoSender?peer.videoSender.replaceTrack(track):Promise.resolve()));updateCallControls();updateLocalPreview();publishMediaState();}catch(err){if(stream){for(const track of stream.getTracks())track.stop();if(state.screenStream===stream)state.screenStream=null;}updateCallControls();updateLocalPreview();const message=err.name==='NotAllowedError'?'Screen sharing was cancelled or blocked. Choose a screen or window in the browser prompt and allow sharing.':`Could not share your screen: ${err.message}`;$('#call-status').textContent=message;toast(message);}}
async function leaveCall(sendBye=true){if(state.callSpeaking&&state.room&&sendBye)announceRoomActivity('');clearInterval(state.speechTimer);state.speechTimer=null;state.speechContext?.close().catch(()=>{});state.speechContext=null;state.callSpeaking=false;state.callJoined=false;state.callStarting=null;state.callConnectionIssue='';if(sendBye&&state.room)for(const peer of state.peers.values())sendSignal(peer.remote,{type:'bye'}).catch(()=>{});for(const peer of state.peers.values())peer.pc.close();state.peers.clear();$('#video-grid').querySelectorAll('.video-tile:not(.local-tile)').forEach(tile=>tile.remove());if(state.screenStream){const stream=state.screenStream;state.screenStream=null;stream.getTracks().forEach(track=>track.stop());}if(state.localStream)state.localStream.getTracks().forEach(track=>track.stop());state.localStream=null;state.microphoneEnabled=false;state.cameraEnabled=false;updateLocalPreview();updateCallControls();}
$('#microphone-toggle').addEventListener('click',()=>setMediaEnabled('audio',!state.microphoneEnabled).catch(err=>{const message=mediaErrorMessage(err,'microphone');$('#call-status').textContent=message;toast(message);}));
$('#camera-toggle').addEventListener('click',()=>setMediaEnabled('video',!state.cameraEnabled).catch(err=>{const message=mediaErrorMessage(err,'camera');$('#call-status').textContent=message;toast(message);}));
$('#end-call').addEventListener('click',()=>leaveCall());
$('#screen-share').addEventListener('click',toggleScreenShare);
$('#call-check').addEventListener('click',checkCallConnection);

init();
